module tb;
    reg [7:0] in;
    wire parity;

    TopModule dut (
        .in(in),
        .parity(parity)
    );

    initial begin
        integer i;
        reg expected;
        for (i = 0; i < 256; i = i + 1) begin
            in = i[7:0];
            #1;
            expected = ^in[7:0];
            if (parity !== expected) begin
                $display("SELFTEST FAIL: in=%b, got=%b, expected=%b", in, parity, expected);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
